<script lang="ts">
  import { app, actions, isAdmin, leaveBalance, displayName } from '#lib/state/app';
  import type { Employee, Role } from '#lib/types';
  import PageHeading from '#lib/components/PageHeading.svelte';
  import Icon from '#lib/components/Icon.svelte';
  import StatusPill from '#lib/components/StatusPill.svelte';
  import EmptyState from '#lib/components/EmptyState.svelte';
  import Modal from '#lib/components/Modal.svelte';
  import Feedback from '#lib/components/Feedback.svelte';
  import { dateLabel, initials, todayJakarta } from '#lib/components/format';

  let search = '', outletFilter = '', departmentFilter = '', statusFilter = 'active';
  let editing = false, selected: Employee | null = null, saving = false, message = '', failed = false;
  let linkResult: { url: string; message: string; expiresAt: string } | null = null;
  const weekdays = ['Minggu', 'Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu'];
  const blank = (): Partial<Employee> => ({ fullName: '', phone: '', departmentId: '', positionId: '', outletId: '', managerId: null, joinDate: todayJakarta(), status: 'active', employmentType: 'permanent', roles: ['employee'], canMiddleShift: false, weeklyOffDays: [0], approvalMode: 'internal', address: '', birthDate: '', gender: '', emergencyName: '', emergencyPhone: '' });
  let form = blank();
  $: admin = isAdmin($app.user ?? undefined);
  $: rows = $app.employees.filter((employee) => (!search || `${employee.fullName} ${employee.employeeNumber}`.toLowerCase().includes(search.toLowerCase())) && (!outletFilter || employee.outletId === outletFilter) && (!departmentFilter || employee.departmentId === departmentFilter) && (!statusFilter || employee.status === statusFilter));
  $: positions = $app.positions.filter((position) => position.departmentId === form.departmentId && (position.active || position.id === form.positionId));
  const departmentName = (id: string) => $app.departments.find((item) => item.id === id)?.name ?? '—';
  const positionName = (id: string) => $app.positions.find((item) => item.id === id)?.name ?? '—';
  const outletName = (id: string) => $app.outlets.find((item) => item.id === id)?.name ?? '—';
  const accountLabel: Record<string, string> = { not_invited: 'Belum diundang', invited: 'Menunggu aktivasi', active: 'Aktif', disabled: 'Dinonaktifkan' };

  function edit(employee: Employee | null) { form = employee ? { ...employee, roles: [...employee.roles], weeklyOffDays: [...employee.weeklyOffDays] } : blank(); selected = null; editing = true; message = ''; linkResult = null; }
  function toggleRole(role: Role, checked: boolean) { const roles = form.roles ?? ['employee']; form = { ...form, roles: checked ? [...new Set([...roles, role])] : roles.filter((item) => item !== role) }; }
  function toggleOff(day: number, checked: boolean) { const days = form.weeklyOffDays ?? []; form = { ...form, weeklyOffDays: checked ? [...new Set([...days, day])] : days.filter((item) => item !== day) }; }
  async function save() { saving = true; message = ''; try { if (!form.departmentId || !form.positionId || !form.outletId) throw new Error('Pilih departemen, jabatan, dan outlet terlebih dahulu.'); await actions.saveEmployee(form); editing = false; failed = false; message = form.id ? 'Data karyawan berhasil diperbarui.' : 'Karyawan berhasil didaftarkan. Buat tautan aktivasi dari profilnya.'; } catch (error) { failed = true; message = error instanceof Error ? error.message : 'Data belum berhasil disimpan.'; } finally { saving = false; } }
  async function issue(purpose: 'activate' | 'reset') { if (!selected) return; saving = true; message = ''; try { linkResult = await actions.issueLink(selected.id, purpose); failed = false; } catch (error) { failed = true; message = error instanceof Error ? error.message : 'Tautan belum berhasil dibuat.'; } finally { saving = false; } }
  async function copyInvite() { if (!linkResult) return; try { await navigator.clipboard.writeText(linkResult.message); message = 'Pesan undangan disalin. Kirim manual melalui WhatsApp.'; failed = false; } catch { failed = true; message = 'Tidak dapat menyalin otomatis. Salin pesan undangan di bawah.'; } }
</script>

<PageHeading eyebrow="TIM JABODETABEK" title="Data karyawan" description="Satu tempat untuk mengenal tim dan mengelola informasi kerjanya.">
  {#if admin}<button class="btn btn-primary" on:click={() => edit(null)}><Icon name="plus" size={18}/>Tambah karyawan</button>{/if}
</PageHeading>
<Feedback {message} error={failed}/>

{#if !admin}<EmptyState icon="shield" title="Akses khusus Admin HR" description="Informasi pribadi Anda tersedia pada halaman Profil."/>{:else}
  <div class="overview"><div><span class="count">{$app.employees.filter((e) => e.status === 'active').length}</span><span>karyawan aktif</span></div><div><span class="count">{$app.departments.filter((d) => d.active).length}</span><span>departemen</span></div><div><span class="count">{$app.outlets.filter((o) => o.active).length}</span><span>outlet</span></div><div class="overview-note"><Icon name="shield" size={18}/><span>Data pribadi hanya untuk pihak berwenang</span></div></div>
  <section class="panel employee-panel">
    <div class="filters"><div class="search"><Icon name="search" size={18}/><input aria-label="Cari karyawan" placeholder="Cari nama atau nomor karyawan…" bind:value={search}/></div><select class="select" aria-label="Filter departemen" bind:value={departmentFilter}><option value="">Semua departemen</option>{#each $app.departments as d}<option value={d.id}>{d.name}</option>{/each}</select><select class="select" aria-label="Filter outlet" bind:value={outletFilter}><option value="">Semua outlet</option>{#each $app.outlets as o}<option value={o.id}>{o.name}</option>{/each}</select><select class="select" aria-label="Filter status karyawan" bind:value={statusFilter}><option value="active">Aktif</option><option value="inactive">Nonaktif</option><option value="">Semua status</option></select></div>
    {#if rows.length}<div class="table-wrap"><table><thead><tr><th>Karyawan</th><th>Departemen & jabatan</th><th>Penempatan</th><th>Status akun</th><th></th></tr></thead><tbody>{#each rows as employee}<tr><td><button class="person" on:click={() => { selected = employee; linkResult = null; message = ''; }}><span class="avatar">{initials(employee.fullName)}</span><span><strong>{employee.fullName}</strong><small>{employee.employeeNumber}</small></span></button></td><td><span>{positionName(employee.positionId)}</span><small>{departmentName(employee.departmentId)}</small></td><td>{outletName(employee.outletId)}</td><td><StatusPill label={accountLabel[employee.accountStatus]} tone={employee.accountStatus === 'active' ? 'green' : employee.accountStatus === 'invited' ? 'amber' : 'muted'}/></td><td><button class="row-arrow" aria-label={`Lihat profil ${employee.fullName}`} on:click={() => { selected = employee; linkResult = null; message = ''; }}><Icon name="chevron" size={17}/></button></td></tr>{/each}</tbody></table></div><div class="table-foot">Menampilkan {rows.length} karyawan</div>{:else}<EmptyState icon="users" title="Tidak ada karyawan yang ditemukan" description="Ubah pencarian atau tambahkan karyawan baru untuk memulai."/>{/if}
  </section>
{/if}

<Modal open={selected !== null} title="Profil karyawan" description="Informasi pekerjaan, akun, dan kontak." onclose={() => { selected = null; linkResult = null; }}>
  {#if selected}
    <div class="profile-head"><span class="avatar large">{initials(selected.fullName)}</span><div><h3>{selected.fullName}</h3><p>{selected.employeeNumber} · {positionName(selected.positionId)}</p><StatusPill label={selected.status === 'active' ? 'Karyawan aktif' : 'Karyawan nonaktif'} tone={selected.status === 'active' ? 'green' : 'muted'}/></div></div>
    <dl class="details"><div><dt>Departemen</dt><dd>{departmentName(selected.departmentId)}</dd></div><div><dt>Outlet</dt><dd>{outletName(selected.outletId)}</dd></div><div><dt>Atasan langsung</dt><dd>{selected.managerId ? displayName(selected.managerId) : selected.approvalMode === 'external' ? 'Persetujuan eksternal' : 'Belum ditetapkan'}</dd></div><div><dt>Tanggal masuk</dt><dd>{dateLabel(selected.joinDate)}</dd></div><div><dt>WhatsApp</dt><dd>{selected.phone || '—'}</dd></div><div><dt>Saldo cuti tahun ini</dt><dd>{leaveBalance(selected.id)} hari</dd></div><div><dt>Hari libur tetap</dt><dd>{selected.weeklyOffDays.map((day) => weekdays[day]).join(', ') || 'Belum diatur'}</dd></div><div><dt>Hubungan kerja</dt><dd>Tetap</dd></div><div><dt>Alamat</dt><dd>{selected.address || 'Belum dilengkapi'}</dd></div><div><dt>Kontak darurat</dt><dd>{selected.emergencyName || 'Belum dilengkapi'}{selected.emergencyPhone ? ` · ${selected.emergencyPhone}` : ''}</dd></div></dl>
    <div class="profile-actions"><button class="btn btn-secondary" on:click={() => edit(selected)}><Icon name="edit" size={16}/>Edit data</button>{#if selected.status === 'active'}<button class="btn btn-primary" disabled={saving} on:click={() => issue(selected?.accountStatus === 'active' ? 'reset' : 'activate')}><Icon name="lock" size={16}/>{selected.accountStatus === 'active' ? 'Tautan pemulihan' : 'Buat tautan aktivasi'}</button>{/if}</div>
    {#if linkResult}<div class="invite"><strong>Siap dikirim melalui WhatsApp</strong><p>Tautan berlaku sampai {dateLabel(linkResult.expiresAt)} {new Date(linkResult.expiresAt).toLocaleTimeString('id-ID', { timeZone: 'Asia/Jakarta', hour: '2-digit', minute: '2-digit' })} WIB.</p><textarea class="textarea" aria-label="Pesan undangan WhatsApp" readonly rows="5" value={linkResult.message}></textarea><button class="btn btn-primary" on:click={copyInvite}>Salin pesan</button></div>{/if}
    <Feedback {message} error={failed}/>
  {/if}
</Modal>

<Modal open={editing} title={form.id ? 'Edit data karyawan' : 'Daftarkan karyawan'} description="Nomor karyawan dibuat otomatis. Informasi pribadi dapat dilengkapi kemudian." onclose={() => editing = false}>
  <form on:submit|preventDefault={save}>
    <div class="form-grid"><label class="field span">Nama lengkap<input class="input" bind:value={form.fullName} required autocomplete="name"/></label><label class="field">Nomor WhatsApp<input class="input" type="tel" bind:value={form.phone} required autocomplete="tel" placeholder="08…"/></label><label class="field">Tanggal masuk<input class="input" type="date" bind:value={form.joinDate} required/></label><label class="field">Departemen<select class="select" bind:value={form.departmentId} on:change={() => form = { ...form, positionId: '' }} required><option value="">Pilih departemen</option>{#each $app.departments.filter((d) => d.active || d.id === form.departmentId) as d}<option value={d.id}>{d.name}</option>{/each}</select></label><label class="field">Jabatan<select class="select" bind:value={form.positionId} required disabled={!form.departmentId}><option value="">Pilih jabatan</option>{#each positions as p}<option value={p.id}>{p.name}</option>{/each}</select></label><label class="field">Penempatan<select class="select" bind:value={form.outletId} required><option value="">Pilih outlet</option>{#each $app.outlets.filter((o) => o.active || o.id === form.outletId) as o}<option value={o.id}>{o.name}</option>{/each}</select></label><label class="field">Atasan langsung<select class="select" bind:value={form.managerId}><option value={null}>Belum ditetapkan / eksternal</option>{#each $app.employees.filter((e) => e.status === 'active' && e.id !== form.id) as e}<option value={e.id}>{e.fullName}</option>{/each}</select></label></div>
    <fieldset><legend>Akses & pengaturan</legend><label class="check"><input type="checkbox" checked={form.roles?.includes('admin_hr')} on:change={(event) => toggleRole('admin_hr', event.currentTarget.checked)}/>Akses Admin HR</label><label class="check"><input type="checkbox" checked={form.roles?.includes('head_baker')} on:change={(event) => toggleRole('head_baker', event.currentTarget.checked)}/>Pemberi persetujuan Head Baker</label><label class="check"><input type="checkbox" bind:checked={form.canMiddleShift}/>Diizinkan menggunakan shift Middle</label><label class="check"><input type="checkbox" checked={form.approvalMode === 'external'} on:change={(event) => form = { ...form, approvalMode: event.currentTarget.checked ? 'external' : 'internal' }}/>Pengajuan memerlukan persetujuan Bos / Manager Pusat</label></fieldset>
    <fieldset><legend>Hari libur mingguan tetap</legend><div class="days">{#each weekdays as day, index}<label class="day"><input type="checkbox" checked={form.weeklyOffDays?.includes(index)} on:change={(event) => toggleOff(index, event.currentTarget.checked)}/><span>{day.slice(0, 3)}</span></label>{/each}</div><p class="hint">Untuk karyawan selain kasir. Kasir mengikuti catatan shift.</p></fieldset>
    {#if form.id}<details><summary>Informasi pribadi & status</summary><div class="form-grid extra"><label class="field span">Alamat<textarea class="textarea" rows="2" bind:value={form.address}></textarea></label><label class="field">Tanggal lahir<input class="input" type="date" bind:value={form.birthDate}/></label><label class="field">Jenis kelamin<select class="select" bind:value={form.gender}><option value="">Belum diisi</option><option value="male">Laki-laki</option><option value="female">Perempuan</option></select></label><label class="field">Nama kontak darurat<input class="input" bind:value={form.emergencyName}/></label><label class="field">Nomor kontak darurat<input class="input" type="tel" bind:value={form.emergencyPhone}/></label><label class="field">Status karyawan<select class="select" bind:value={form.status}><option value="active">Aktif</option><option value="inactive">Nonaktif</option></select></label>{#if form.status === 'inactive'}<label class="field">Tanggal keluar<input class="input" type="date" bind:value={form.exitDate} required/></label><label class="field span">Alasan keluar<textarea class="textarea" bind:value={form.exitReason} required rows="2"></textarea></label><p class="hint span">Akses akun ditutup. Riwayat karyawan tetap disimpan. Alihkan anggota tim sebelum menonaktifkan atasan.</p>{/if}</div></details>{/if}
    <Feedback {message} error={failed}/><div class="form-actions"><button type="button" class="btn btn-secondary" on:click={() => editing = false}>Batal</button><button class="btn btn-primary" type="submit" disabled={saving}>{saving ? 'Menyimpan…' : 'Simpan karyawan'}</button></div>
  </form>
</Modal>

<style>
.overview{display:flex;gap:2.5rem;align-items:center;padding:.2rem 0 1.7rem}.overview>div{display:flex;align-items:baseline;gap:.6rem;font-size:.75rem;color:var(--muted)}.count{font-size:1.7rem;color:var(--muted);letter-spacing:-.04em;font-weight:650}.overview .overview-note{margin-left:auto;align-items:center;font-size:.7rem;max-width:230px;color:var(--muted)}.employee-panel{overflow:hidden;padding:0}.filters{display:grid;grid-template-columns:1.5fr 1fr 1fr .8fr;gap:.65rem;padding:1.25rem;border-bottom:1px solid var(--border)}.search{display:flex;align-items:center;gap:.65rem;border:1px solid var(--border);border-radius:9px;padding:0 .85rem;color:var(--muted);background:#fff}.search input{width:100%;padding:.7rem 0;border:0;outline:0;background:transparent;font-size:.8rem}.table-wrap{overflow-x:auto}table{border-collapse:collapse;width:100%;text-align:left}th{font-size:.67rem;text-transform:uppercase;letter-spacing:.065em;color:var(--muted);background:#fcfaf5;padding:1rem 1.25rem;font-weight:600}td{font-size:.8rem;padding:1rem 1.25rem;border-bottom:1px solid var(--border);color:var(--muted);white-space:nowrap}td small{display:block;font-size:.7rem;color:var(--muted);margin-top:.3rem}.person{display:flex;gap:.8rem;align-items:center;text-align:left;background:transparent;border:0;padding:0;cursor:pointer;color:var(--muted)}.person strong{font-size:.82rem;font-weight:600}.person small{font-size:.69rem;margin-top:.35rem}.avatar{width:38px;height:38px;background:#f4efdf;color:var(--muted);border:1px solid var(--border);display:grid;place-items:center;border-radius:12px;font-size:.72rem;font-weight:650;flex-shrink:0}.row-arrow{background:transparent;border:0;color:var(--muted);padding:.5rem;cursor:pointer}.table-foot{font-size:.7rem;color:var(--muted);padding:1rem 1.25rem}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:1rem}.span{grid-column:1/-1}fieldset{border:0;padding:1.2rem 0;margin:1.2rem 0 0;border-top:1px solid var(--border)}legend{font-size:.82rem;font-weight:600;padding:0 .5rem 0 0}.check{display:flex;gap:.6rem;align-items:flex-start;font-size:.8rem;margin:.6rem 0;color:var(--muted);line-height:1.5}.check input{margin-top:.2rem;accent-color:#716640}.days{display:flex;gap:.4rem;flex-wrap:wrap}.day input{position:absolute;opacity:0;width:1px;height:1px}.day span{display:block;padding:.55rem .7rem;border:1px solid var(--border);background:#fbfaf4;border-radius:8px;font-size:.74rem;color:var(--muted);cursor:pointer}.day input:checked+span{background:#f1ead3;border-color:var(--border);color:var(--muted)}.day input:focus-visible+span{outline:2px solid #716640;outline-offset:2px}.hint{font-size:.7rem;color:var(--muted);line-height:1.6}.form-actions{display:flex;justify-content:flex-end;gap:.6rem;border-top:1px solid var(--border);margin-top:1rem;padding-top:1.2rem}.profile-head{display:flex;gap:1rem;align-items:center;margin-bottom:1.5rem}.avatar.large{width:64px;height:64px;border-radius:18px;font-size:1.25rem}.profile-head h3{margin:0 0 .4rem;font-size:1.25rem;letter-spacing:-.04em}.profile-head p{font-size:.78rem;color:var(--muted);margin:0 0 .65rem}.details{display:grid;grid-template-columns:1fr 1fr;gap:1.25rem;margin:0}.details dt{font-size:.67rem;color:var(--muted);margin:0 0 .4rem}.details dd{font-size:.81rem;line-height:1.5;margin:0;color:var(--muted)}.profile-actions{display:flex;flex-wrap:wrap;gap:.6rem;margin-top:1.6rem;padding-top:1.3rem;border-top:1px solid var(--border)}.invite{padding:1rem;background:#f9f6ec;border-radius:12px;margin:1rem 0}.invite strong{font-size:.82rem}.invite p{font-size:.72rem;color:var(--muted)}.invite textarea{width:100%;margin:.5rem 0}.extra{margin-top:1rem}summary{font-size:.82rem;cursor:pointer;color:var(--muted);padding:.6rem 0}@media(max-width:1000px){.filters{grid-template-columns:1fr 1fr}.search{grid-column:1/-1}.overview{gap:1.5rem}.overview .overview-note{display:none}}@media(max-width:600px){.overview{gap:1.15rem;padding-bottom:1.2rem}.overview>div{gap:.3rem;font-size:.62rem}.count{font-size:1.45rem}.filters{padding:.9rem;gap:.5rem}.filters .select{font-size:.72rem}.form-grid{grid-template-columns:1fr}.span{grid-column:auto}.details{gap:1rem}.profile-actions .btn{flex:1}th,td{padding:.85rem 1rem}}
  .count, .person, .profile-head h3, .details dd, legend { color: var(--ink); }
  .search { background: var(--surface); border-color: var(--control-border); box-shadow: var(--inset); border-radius: 12px; }
  .search:focus-within { outline: 2px solid #7c6f46; outline-offset: 2px; }
  .search input { min-height: 46px; color: var(--ink); }
  .search input::placeholder { color: var(--muted); }
  th { background: #f1ebd6; }
  td { color: #5f5535; }
  tbody tr:hover { background: #f1ead4; }
  .person { min-height: 44px; }
  .avatar { background: var(--surface); color: var(--accent); border-color: var(--panel-border); box-shadow: var(--raised-sm); border-radius: 13px; }
  .row-arrow { min-width: 44px; min-height: 44px; color: var(--accent); border-radius: 11px; }
  .row-arrow:hover { box-shadow: var(--raised-sm); }
  .day span { background: var(--surface); color: var(--accent); border-color: var(--control-border); box-shadow: var(--raised-sm); border-radius: 10px; min-height: 42px; padding: .7rem .8rem; }
  .day input:checked + span { background: #efe7ce; border-color: #8f8050; color: #51492e; box-shadow: var(--inset); }
  .invite { background: var(--surface-cream); border: 1px solid var(--panel-border); box-shadow: var(--inset); border-radius: 15px; }
  summary { color: var(--accent); min-height: 44px; }
  @media (max-width: 600px) { .search input { font-size: 16px; } }
</style>
